def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'D'
    if n == 4:
        if history[3][1] == 'C':
            return 'D'
        else:
            return 'C'
    if n == 5:
        if history[4][1] == 'C':
            return 'D'
        else:
            return 'C'
    if n == 99:
        return 'D'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    total_opp_def = sum(1 for x in opp if x == 'D')
    if total_opp_def == 0:
        return 'D'
    if total_opp_def > n * 0.6:
        if n % 10 == 0:
            return 'C'
        return 'D'
    last_opp = opp[-1]
    last_me = me[-1]
    if last_opp == 'C':
        return 'C'
    else:
        consec = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                consec += 1
            else:
                break
        if consec >= 3:
            return 'D'
        if consec == 2:
            if last_me == 'C':
                return 'C'
            else:
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
        if consec == 1:
            if last_me == 'D':
                return 'C'
            else:
                return 'D'
    return 'C'
